-- SQL baseline (applied to production 2026-10-03, PostgreSQL 18; compatible with 16).
-- Changes go through a reviewed PR; Phase B moves this into Drizzle migrations.
-- ids are generated by the application (no DB defaults).

-- Platform-level table: one row per tenant. Not clinic-scoped by RLS (accessed by platform role only).
CREATE TABLE clinics (
  id               uuid PRIMARY KEY,
  slug             text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name_ar          text NOT NULL,
  name_en          text NOT NULL,
  specialty        text NOT NULL CHECK (specialty IN ('psychiatry','psychology','dental','dermatology','obgyn','general')),
  default_language text NOT NULL CHECK (default_language IN ('ar','en')),
  timezone         text NOT NULL,
  status           text NOT NULL CHECK (status IN ('trial','active','suspended')),
  expires_at       timestamptz NOT NULL,
  max_users        integer NOT NULL CHECK (max_users > 0),
  max_branches     integer NOT NULL CHECK (max_branches > 0),
  created_at       timestamptz NOT NULL,
  updated_at       timestamptz NOT NULL
);
CREATE INDEX clinics_status_expires_idx ON clinics (status, expires_at);
